package zeldaCV.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Hashing of guestbook message passwords. The password is a long random value generated by the
 * browser (not chosen by a human), so a fast SHA-256 is enough: no salt or slow hash is needed
 * to resist brute force. Hashing only avoids keeping usable passwords if the database leaks.
 */
public final class CommentPassword {

    private CommentPassword() {
    }

    public static String hash(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(password.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Constant-time comparison of a candidate password with a stored hash. */
    public static boolean matches(String password, String storedHash) {
        if (password == null || storedHash == null) {
            return false;
        }
        return MessageDigest.isEqual(
                hash(password).getBytes(StandardCharsets.US_ASCII),
                storedHash.getBytes(StandardCharsets.US_ASCII));
    }
}
